import{z as l,x as o,o as B,c as d,q as r,j as s,D as e,d as a,s as i,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"债券组合案例","description":"","frontmatter":{"title":"债券组合案例","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-case.md","filePath":"quant/bm2-case.md","lastUpdated":1791413859000}'),p={name:"quant/bm2-case.md"};function D(m,E,C,F,u,h){const t=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="债券组合案例" tabindex="-1">债券组合案例 <a class="header-anchor" href="#债券组合案例" aria-label="Permalink to &quot;债券组合案例&quot;">​</a></h1><div class="epigraph"><p>案例不新增工具，只考验次序：先负债，再利率层，后信用层，最后把抵押与条款放进压力里——顺序错了，每个工具单独都对，合起来是错的。</p><footer>—— 据 Fabozzi, Bond Markets, Analysis and Strategies 组合管理章节的流程整理</footer></div><p><a href="/quant/bm2-credit-diversification">上一课</a>把信用层的目标写成损失分布，本课程的工具至此齐备：免疫的匹配循环、LDI 的切分、指数化的特征复制、期货与互换的分工。本课把它们按正确顺序装进一台组合——一个养老金的资产负债案例，从负债档案走到压力报告。数字为教学口径，方案结构为正题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一台养老金：负债现值 100，加权久期 12，支付谱跨 3 到 30 年，一半支付挂通胀；资金比率 100%；治理要求一年内资金比率下行不超过 5 个百分点，回报目标由收益组合承担。要做的决策有四个：负债匹配用什么工具组合、对冲比率定多少、收益组合多大、压力怎么定。缺口的陷阱在次序：先想收益再想对冲的组合，会在利差走阔的那个月同时吃利率与信用两刀；先定风险单位的组合，每一刀都有对应的账本。</p><p><span class="marginnote">术语翻译：资金比率 100% 就是「用来还债的资产现值」恰好等于「要还的负债现值」——比率掉到 95%，意味着同样一笔债，资产只够还九成五。治理要求「一年内下行不超过 5 个百分点」，就是给这个比率画一条不得跌破的警戒线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，负债档案：按 <a href="/quant/key-tenor-dv01">关键期限 DV01</a> 分桶，3 到 30 年各桶的 DV01 向量是全部后续决策的风险单位；通胀腿单列，名义工具对它失明。第二步，利率层：长端（20 年以上）用 <a href="/quant/bm2-swaps-in-portfolio">收固互换</a> 覆盖，中期用 <a href="/quant/bm2-treasury-futures">国债期货</a> 覆盖并保留战术调整的余地，短端留现金与短债；对冲比率按预算定在八成——以负债久期 12 计，每 100 个基点平行的负债一阶变动约 12%，八成对冲后残余约 2.4%，这个数写进限额。第三步，信用层：收益组合内的信用敞口按 <a href="/quant/bm2-credit-diversification">分散的算术</a> 构造，系统层用指数对冲掉一部分利差贝塔。第四步，抵押路径：互换 CSA 与期货保证金的极端需求预筹现金，触发线写进治理文件（<a href="/quant/bm2-ldi">LDI 一课</a> 的判据）。第五步，<a href="/quant/pf-stress-testing">压力测试</a>：平行 ±200 个基点、陡化与平坦化、利差 +150 个基点、相关趋一，各场景同时触发追保。</p><p><span class="marginnote">术语翻译：DV01 就是「利率动一个基点（0.01%），组合价值变多少」。负债久期 12 意味着利率平行上 100 个基点，负债现值约变动 12%；八成对冲后剩下 2.4%——这就是写进限额的那个残余数字的来历。</span></p>',9)),(B(),s(n,null,{default:e(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIA%5B%22%E8%B4%9F%E5%80%BA%E6%A1%A3%E6%A1%88%EF%BC%9ADV01%20%E5%90%91%E9%87%8F%E4%B8%8E%E9%80%9A%E8%83%80%E8%85%BF%22%5D%20--%3E%20RL%5B%22%E5%88%A9%E7%8E%87%E5%B1%82%EF%BC%9A%E4%BA%92%E6%8D%A2%E8%A1%A5%E9%95%BF%E7%AB%AF%EF%BC%8C%E6%9C%9F%E8%B4%A7%E8%A1%A5%E4%B8%AD%E6%9C%9F%22%5D%0A%20%20RL%20--%3E%20CL%5B%22%E4%BF%A1%E7%94%A8%E5%B1%82%EF%BC%9A%E7%B2%92%E5%BA%A6%E7%BA%A6%E6%9D%9F%E5%8A%A0%E6%8C%87%E6%95%B0%E5%AF%B9%E5%86%B2%22%5D%0A%20%20CL%20--%3E%20RP%5B%22%E6%94%B6%E7%9B%8A%E7%BB%84%E5%90%88%EF%BC%9A%E5%89%A9%E4%BD%99%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E5%86%85%22%5D%0A%20%20RP%20--%3E%20CM%5B%22%E6%8A%B5%E6%8A%BC%E8%B7%AF%E5%BE%84%EF%BC%9ACSA%20%E4%B8%8E%E4%BF%9D%E8%AF%81%E9%87%91%E9%A2%84%E7%AD%B9%22%5D%0A%20%20CM%20--%3E%20ST%5B%22%E5%8E%8B%E5%8A%9B%EF%BC%9A%E5%B9%B3%E8%A1%8C%E3%80%81%E9%99%A1%E5%B9%B3%E3%80%81%E5%88%A9%E5%B7%AE%E3%80%81%E7%9B%B8%E5%85%B3%E8%B6%8B%E4%B8%80%22%5D%0A%20%20ST%20--%3E%20GV%7B%22%E6%98%AF%E5%90%A6%E7%A0%B4%E9%99%90%E9%A2%9D%22%7D%0A%20%20GV%20--%3E%20AD%5B%22%E8%B0%83%E5%AF%B9%E5%86%B2%E6%AF%94%E7%8E%87%E6%88%96%E9%99%8D%E9%A3%8E%E9%99%A9%22%5D%0A%20%20GV%20--%3E%20OK%5B%22%E7%9B%91%E6%8E%A7%E8%BF%90%E8%A1%8C%22%5D%0A%20%20AD%20--%3E%20RL%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("次序为什么这样排：负债定义风险单位，一切敏感度换算成对负债的口径，这是 LDI 立下的判据；利率层先于信用层，因为 "),A("a",{href:"/quant/curve-pca"},"因子分解"),a(" 的证据显示水平因子承载了国债收益的大部分方差，主战场在曲线；信用层的规模由损失分布的尾部预算决定，不由期望收益决定——期望收益在 EL 里与相关无关，风险全在 UL；工具按总成本比较：期货便宜但带 CTD 刻度漂移，互换灵活但带抵押条款，现券最贵但兑现凸性与 carry——每一段负债用总成本最小的工具去匹配。抵押路径是约束不是事后：2022 年的教训是它在传导链的最上游。")],-1)),(B(),s(n,null,{default:e(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20DEBT%5B%22%E8%B4%9F%E5%80%BA%20DV01%20%E5%90%91%E9%87%8F%E6%8C%89%E6%9C%9F%E9%99%90%E5%88%86%E6%A1%B6%22%5D%20--%3E%20S1%5B%22%E7%9F%AD%E7%AB%AF%20%E7%8E%B0%E9%87%91%E4%B8%8E%E7%9F%AD%E5%80%BA%22%5D%0A%20%20DEBT%20--%3E%20S2%5B%22%E4%B8%AD%E6%9C%9F%20%E5%9B%BD%E5%80%BA%E6%9C%9F%E8%B4%A7%20%E7%95%99%E6%88%98%E6%9C%AF%E4%BD%99%E5%9C%B0%22%5D%0A%20%20DEBT%20--%3E%20S3%5B%22%E9%95%BF%E7%AB%AF%20%E6%94%B6%E5%9B%BA%E4%BA%92%E6%8D%A2%22%5D%0A%20%20S1%20--%3E%20TC%5B%22%E6%AF%8F%E6%AE%B5%E7%94%A8%E6%80%BB%E6%88%90%E6%9C%AC%E6%9C%80%E5%B0%8F%E7%9A%84%E5%B7%A5%E5%85%B7%22%5D%0A%20%20S2%20--%3E%20TC%0A%20%20S3%20--%3E%20TC%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">直觉类比：「相关趋一」的压力场景像全城同时断电——平时债券与股票、信用与利率互为对冲，靠的是它们不同时出问题；危机里所有资产一起跳水，分散的算术失灵。压力报告必须单列这个场景，就是给「对冲同时失效」留一次演习。</span></p><p><span class="marginnote">本案例的数字都对得上：负债 DV01 每 100 个基点约 12，对冲八成剩 2.4，利差 +150 个基点与相关趋一的场景把信用层尾部压到限额边缘——压力报告的价值不在某个数字，而在每个数字都有一条写明的条款与之对应。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例的数字是教学口径：真实负债的现金流与通胀挂钩比例要按精算档案重算，监管折现率与经济口径的差会让同一台组合有两张损益表。案例没写的事也不少：跨币种负债的汇率腿、通胀工具的细节、证券化产品的负凸性，各是独立课题；收益组合的 alpha 来源全部外生假定，本课程不负责证明它存在。最要紧的边界是：这是一台「不输在结构上」的组合，不是一台「一定赢」的组合——结构保证的是坏情形有条款、有账本、有触发线，收益仍来自市场给的那些风险溢价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>次序即方法：负债档案、利率层、信用层、抵押路径、压力报告，不可交换。</li><li>风险单位是关键期限 DV01 向量，对冲比率按预算定并写成限额。</li><li>工具按总成本比较分配到各期限段：期货、互换、现券各管一段。</li><li>抵押与追保路径预筹并设触发线，压力场景必须包含相关趋一。</li><li>出处：据 Fabozzi 组合管理章节的流程整理；各工具机制见本课程相应各课，压力判据见压力测试相关课。</li></ul>',6))])}const b=l(p,[["render",D]]);export{c as __pageData,b as default};
